"""Explain wait entry setup, declarations, flag snapshots and simple waits."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1489': ('대기 신청서를 준비한다고 생각해 봅시다. 누구를 기다리는 줄에 넣을지, 부를 때 무엇을 할지, 줄을 어떻게 연결할지를 각각 적어야 합니다. 이름만 적었다고 신청서가 모두 완성되는 것은 아닙니다.', '비슷한 초기화 함수가 실제로 어느 칸을 채우는지 구별합니다.', 'flags, private, func, entry 네 칸을 그리세요. init_wait_entry가 각 칸에 넣는 값을 적고, init_waitqueue_func_entry가 건드리지 않는 entry 칸에 동그라미를 치세요.', ['초기화는 자료를 처음 사용할 수 있는 상태로 준비하는 일입니다. wait_queue_entry는 대기 신청서 한 장에 해당합니다. flags는 특별한 표시, private는 관련 자료의 주소, func는 깨울 때 부를 함수, entry는 다른 신청서와 연결하는 부분입니다.', 'init_wait_entry는 flags에 호출자가 준 표시를 저장합니다. private에는 current를 넣습니다. current는 지금 이 코드를 실행 중인 태스크, 즉 커널이 실행을 관리하는 작업을 가리킵니다. 다른 사람의 이름을 임의로 넣는 것이 아닙니다.', 'func에는 autoremove_wake_function을 넣습니다. 함수의 위치를 저장하는 것을 함수 포인터라고 합니다. 나중에 다른 코드가 그 함수를 불러 일하게 하는 방식을 콜백이라고 합니다. 위치를 적는 지금 단계에서 곧바로 깨우기를 실행하는 것은 아닙니다.', '이 콜백은 기본 깨우기 함수를 부르고, 그 결과가 0이 아닐 때 대기 항목을 줄에서 빼고 연결을 정리합니다. 결과가 0이면 그 삭제를 하지 않습니다. autoremove라는 이름을 보고 언제나 지우거나 메모리까지 돌려준다고 생각하지 마세요.', 'INIT_LIST_HEAD는 entry의 앞뒤 연결이 자기 자신을 가리키도록 만듭니다. 원형 연결 목록에서 이것은 비어 있는 초기 상태입니다. 아직 다른 대기 줄에 신청서를 붙인 것은 아닙니다. 준비와 실제 등록은 따로 이루어집니다.', '비슷한 이름의 init_waitqueue_func_entry는 다릅니다. flags를 0으로, private를 NULL, 즉 대상 없음으로, func를 사용자가 준 함수로 정합니다. entry 연결은 건드리지 않습니다. 따라서 다음에 쓸 함수가 빈 연결을 요구한다면 별도로 초기화해야 하고, 콜백에 필요한 private 자료도 그 규칙에 맞게 준비해야 합니다.'], [('init_wait_entry가 “나중에 깨울 때 부를 함수” 칸에 적는 이름은?', ['아무 함수도 없다는 NULL이에요', 'autoremove_wake_function이에요'], 'func 칸에 autoremove_wake_function을 직접 저장합니다. NULL을 넣는다는 답은 틀려요. 저장은 예약할 동작을 정하는 단계이며 지금 바로 그 함수를 실행하거나 대기 줄에 등록하는 단계는 아닙니다.'), ('init_waitqueue_func_entry만 호출했어요. 앞뒤 연결도 자동으로 자기 자신을 가리킬까요?', ['아니요. 이 함수는 연결 칸을 초기화하지 않아요', '네. init_wait_entry와 모든 칸을 똑같이 채워요'], '이 함수가 쓰는 칸은 flags, private, func입니다. entry에 INIT_LIST_HEAD를 하지 않으므로 연결까지 준비되었다고 가정하면 안 돼요. 다음에 사용할 함수가 요구하는 상태를 따로 마련해야 합니다.')]), 'os1490': ('가게 안내판에 “주문은 숫자 두 개를 받아요”라고 쓰여 있어도, 음식을 만드는 순서까지 알 수는 없습니다. 코드에도 사용 모양을 알려 주는 선언과 실제 일을 적은 본체가 따로 있습니다.', '함수 선언과 실제 동작, 함수 포인터의 뜻을 구별합니다.', 'int add(int a, int b);를 적고 “입력 두 개, 정수 결과, 계산법은 아직 모름”이라고 쓰세요. 아래에 int add(int a, int b) { return a + b; }를 적고 계산법을 찾아보세요.', ['헤더는 여러 소스 파일이 함께 알아야 할 선언 등을 모아 놓는 파일입니다. 보통 .h로 끝납니다. wait.h에는 선언만 있는 함수도 있고, 실제 동작을 적은 매크로도 있습니다. 파일 이름만 보고 전부 같은 종류라고 생각하지 마세요.', '끝부분의 init_wait는 #define으로 만든 매크로입니다. 매크로는 C 코드를 번역하기 전에 이름을 정해 둔 코드로 바꾸는 규칙입니다. 여기서는 private에 current, func에 autoremove_wake_function, flags에 0을 넣고 연결을 자기 자신으로 초기화합니다.', 'init_wait의 current는 지금 실행 중인 작업입니다. autoremove_wake_function은 나중에 깨우기를 맡을 함수입니다. 초기화했을 뿐 아직 대기 줄에 넣거나 작업을 재운 것은 아닙니다. 앞서 본 init_wait_entry는 flags를 인자로 받지만 이 매크로는 0으로 정합니다.', '그 아래 typedef int (*task_call_f)(struct task_struct *p, void *arg)는 함수 포인터 종류에 task_call_f라는 이름을 붙입니다. p는 작업 자료의 주소이고 arg는 추가 자료를 전달할 주소입니다. void *는 구체적인 자료 종류를 이 선언에서 정하지 않은 포인터입니다. 아무 주소나 안전하게 읽을 수 있다는 뜻은 아닙니다.', '맨 앞 int는 호출 결과가 정수라는 뜻입니다. 이 줄만으로 0이 성공인지, 어느 잠금을 잡고 실행하는지는 알 수 없습니다. 정수라는 상자 모양을 아는 것과 그 안 숫자의 약속을 아는 것은 다릅니다. 함수 구현과 사용하는 곳의 규칙을 함께 읽어야 합니다.', 'default_wake_function과 task_call_func의 함수 선언은 끝에 세미콜론 ;이 있습니다. 호출할 이름과 인자, 결과의 자료형을 알리지만 실행 순서를 적은 본체는 여기에 없습니다. 본체는 다른 소스의 정의에서 찾습니다. 함수 포인터를 선언하거나 저장한 것과 실제 호출한 것도 구별하세요.'], [('task_call_f가 정수를 돌려준다는 선언을 읽었어요. 어느 잠금 안에서 실행되는지도 알 수 있나요?', ['네. int라고 쓰면 필요한 잠금이 모두 보장돼요', '아니요. 구현과 호출하는 쪽의 규칙도 읽어야 해요'], 'int는 결과를 담는 자료형입니다. 잠금을 잡는 명령이나 호출 조건을 대신하지 않아요. 안내판에 입력 모양이 적혀 있다고 가게 안 작업 순서를 모두 아는 것은 아닌 것과 같습니다.'), ('wait.h에서 세미콜론으로 끝나는 default_wake_function 선언을 찾았어요. 이것만으로 전체 실행 순서를 읽은 걸까요?', ['아니요. 실제 동작을 적은 정의를 더 찾아야 해요', '네. 함수 이름과 입력 목록이 전체 알고리즘이에요'], '이 선언은 함수를 어떻게 부를지 알려 줍니다. 실제 조건 검사와 실행 명령은 본체에 있어요. 본체를 찾아 연결해야 어떤 경우에 어떻게 깨우는지 설명할 수 있습니다.')]), 'os1491': ('선생님이 신청서의 표시를 종이에 옮겨 적은 뒤 담당자에게 일을 맡겼다고 해 봅시다. 담당자가 원래 신청서 표시를 바꿔도, 선생님이 이미 적은 종이의 값은 자동으로 바뀌지 않습니다.', '표시를 읽은 시점과 나중에 바뀐 값을 구별합니다.', '처음 EXCLUSIVE 켜짐 → 표시 복사 → 콜백이 원본 표시 끔 → 콜백 결과 1을 적으세요. 이번 한도 계산에는 어느 표시가 쓰이는지 동그라미를 치세요.', ['flags는 여러 개의 켜짐·꺼짐 표시를 한 숫자에 담은 것입니다. 비트는 0 또는 1을 담는 작은 자리입니다. 헤더에는 EXCLUSIVE=0x01, WOKEN=0x02, CUSTOM=0x04, DONE=0x08, PRIORITY=0x10이 있습니다. 0x는 16진수 표기이고 여기의 값은 차례로 1, 2, 4, 8, 16입니다.', '각 표시는 서로 다른 비트 자리이므로 함께 켤 수 있습니다. 예를 들어 1과 16의 표시를 OR 연산으로 합치면 17입니다. 숫자가 17이라고 사람이 17명 있다는 뜻은 아닙니다. 어느 자리가 켜져 있는지 읽어야 합니다.', '공통 깨우기 함수 __wake_up_common은 항목 하나를 다룰 때 curr->flags를 지역 변수 flags에 먼저 복사합니다. 지역 변수는 이 실행 안에서 사용하는 별도 칸입니다. 그 뒤 curr->func라는 콜백, 즉 항목에 등록된 함수를 호출합니다.', '콜백 결과가 음수이면 순회를 멈춥니다. 결과가 0이면 이 항목 때문에 깨우기 한도를 줄이지 않습니다. 결과가 양수이고 미리 복사한 EXCLUSIVE가 켜져 있으면 한도를 하나 줄이고, 그 결과 0이 되면 멈춥니다. 콜백 결과와 표시를 함께 확인하는 규칙입니다.', '콜백이 실행되는 동안 원본 EXCLUSIVE를 바꿔도 이번 한도 판단은 먼저 복사한 값으로 합니다. 처음 켜져 있었고 콜백 결과가 1이면, 콜백이 표시를 껐어도 한도를 하나 줄입니다. 반대로 처음 꺼져 있었다면 나중에 켰다는 이유로 이번에 줄이지 않습니다.', '표시 이름을 정의해 두는 것만으로 기능이 저절로 실행되지는 않습니다. PRIORITY는 등록 위치 규칙에, WOKEN은 별도 깨움 알림 규칙에 쓰입니다. 이 공통 순회에는 DONE이나 CUSTOM만 보고 무조건 건너뛰는 검사가 없습니다. 해당 표시를 실제로 읽는 코드나 사용자 콜백까지 찾아야 의미를 알 수 있습니다.'], [('공통 깨우기 코드가 한도를 셀 때 쓸 EXCLUSIVE 표시는 언제 복사하나요?', ['콜백이 끝난 뒤에만 새로 읽어요', '그 항목의 콜백을 부르기 전에 읽어요'], '먼저 unsigned flags = curr->flags로 값을 복사하고 콜백을 부릅니다. 한도를 셀 때는 복사본을 사용해요. 그래서 콜백 안에서 원본 표시를 바꾸어도 이번 계산에 쓰이는 복사본은 바뀌지 않습니다.'), ('이름이 DONE인 표시를 켰어요. 공통 순회가 그 항목을 자동으로 건너뛰나요?', ['아니요. 이 공통 순회에는 DONE만으로 건너뛰는 검사가 없어요', '네. DONE이라는 이름만 있으면 자동으로 건너뛰어요'], '표시를 정의하는 것과 그 표시를 읽고 행동하는 것은 다릅니다. 이 함수는 콜백 결과와 EXCLUSIVE를 확인해요. DONE을 특별히 처리하려면 실제로 그것을 검사하는 코드가 있어야 합니다.')]), 'os1492': ('한 줄에서 번호만 불러 주는 창구와, 사람마다 긴 부탁도 처리하는 창구를 생각해 봅시다. 번호만 부르는 창구는 할 일이 제한되어 있어 한 사람 때문에 창구를 오래 붙잡는 상황을 줄이기 쉽습니다.', 'simple waitqueue가 기능을 줄여 잠금 보유 시간을 다루는 이유를 이해합니다.', '일반 대기 줄에는 사용자 콜백 가능, swait에는 임의 콜백 없음이라고 적으세요. 콜백이 오래 걸리면 그동안 잠금을 기다리는 다른 작업에 어떤 일이 생길지 말해 보세요.', ['swait는 simple waitqueue, 즉 기능을 줄인 대기 줄입니다. 대기 항목에는 task라는 작업 주소와 task_list라는 줄 연결이 있습니다. 일반 waitqueue 항목에 있는 사용자 깨움 함수 func 칸은 없습니다.', '사용자 콜백은 다른 코드가 맡긴 함수입니다. 그 안에서 얼마나 많은 일을 할지 공통 대기 코드만 보고 알기 어렵습니다. 잠금을 잡은 채 긴 콜백을 실행하면 다른 작업은 그 잠금을 더 오래 기다릴 수 있습니다. swait는 임의 콜백 기능을 빼서 이런 불확실성을 줄입니다.', '대기 줄의 잠금은 raw_spinlock_t입니다. 이 잠금은 잠들어서 기다리는 방식으로 바뀌지 않는 낮은 수준의 스핀 잠금입니다. 따라서 잡은 구간을 짧게 다루는 것이 중요합니다. 실시간 제약은 단순히 평균 속도가 빠른 것보다 필요한 응답 시간을 지키는 일이 중요한 상황을 뜻합니다.', '일반 대기 줄처럼 서로 다른 수면 종류를 섞어 조건에 맞는 사람을 찾아다니는 사용도 제한합니다. 깨움은 TASK_NORMAL이라는 상태 묶음을 대상으로 합니다. 일반적인 비 exclusive 모드도 제공하지 않습니다. swake_up_one은 첫 항목 하나를 처리하며, 줄이 비면 아무 항목도 처리하지 않습니다.', '여럿을 깨우는 swake_up_all은 인터럽트를 꺼 둔 상태에서 부르면 안 됩니다. 처리 사이에 잠금과 인터럽트를 풀 수 있어야 오래 붙잡는 시간을 제한할 수 있기 때문입니다. 별도로 completions를 위해 둔 swake_up_all_locked와 이름이 비슷해도 사용 조건을 섞으면 안 됩니다.', '기능을 줄였다고 모든 상황에서 더 좋은 대기 줄이 되지는 않습니다. 사용자 콜백이나 여러 대기 종류를 구별하는 기능이 필요하면 일반 waitqueue가 맞을 수 있습니다. 원문도 특별한 실시간 제약이 있을 때 swait를 쓰고, 보통은 일반 waitqueue를 쓰도록 설명합니다. 필요한 기능과 허용되는 실행 상황을 먼저 확인하세요.'], [('swait 항목에 원하는 깨우기 함수를 마음대로 넣을 수 있나요?', ['네. 일반 waitqueue처럼 func 칸에 아무 함수나 넣어요', '아니요. 임의의 사용자 깨움 콜백 기능을 뺀 구조예요'], '항목에는 작업 주소와 줄 연결이 있고 사용자 func 칸은 없습니다. 임의 함수가 얼마나 오래 실행될지 알기 어려워 그 기능을 제외했어요. 줄인 기능 덕분에 잠금을 잡는 구간을 더 제한하기 쉽습니다.'), ('이름이 simple이니까 모든 대기를 swait로 바꾸는 것이 좋을까요?', ['아니요. 필요한 기능과 특별한 실시간 제약을 먼저 확인해요', '네. 일반 waitqueue의 기능을 모두 갖춘 교체품이에요'], '원문은 대부분의 경우 일반 waitqueue를 쓰는 편을 권합니다. swait는 콜백 등 일부 기능을 줄인 선택이에요. 간단하다는 이름만 보고 바꾸면 원래 필요했던 동작을 제공하지 못할 수 있습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_368.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
